from collections import Counter

def f(grid):
    g=np.array(grid); H,W=g.shape
    cnt=Counter(g.flat); bg=cnt.most_common(1)[0][0]
    rem=[c for c,_ in cnt.most_common() if c!=bg]
    # line color: non-bg color with longest run
    def maxrun(c):
        best=0
        for y in range(H):
            run=0
            for x in range(W):
                run = run+1 if g[y,x]==c else 0; best=max(best,run)
        for x in range(W):
            run=0
            for y in range(H):
                run = run+1 if g[y,x]==c else 0; best=max(best,run)
        return best
    line=max(rem,key=maxrun); seed=[c for c in rem if c!=line][0]
    horizontals = any((g[y]==line).all() for y in range(H))
    out=g.copy()
    def put(y,x,v):
        if 0<=y<H and 0<=x<W and out[y,x]==bg: out[y,x]=v
    for y in range(H):
        for x in range(W):
            if g[y,x]==seed:
                if horizontals:
                    rows_with=[yy for yy in range(H) if (g[yy]==line).any()]
                    foot_y=min(rows_with,key=lambda ry:abs(ry-y)); foot_x=x
                    for r in range(foot_y-1,foot_y+2):
                        for c in range(foot_x-1,foot_x+2):
