                    put(foot_y,foot_x,seed)
                    d=1 if y>foot_y else -1
                    cy=y
                    while cy!=y:  # guard unused; real loop below
                        pass
                    cy=y-d
                    while abs(cy-y)>=1 and 0<=cy<H:
                        cy-=d
                        if g[cy,foot_x]==bg: put(cy,foot_x,seed)
                else:
                    cols_with=[xx for xx in range(W) if (g[:,xx]==line).any()]
                    foot_x=min(cols_with,key=lambda cx:abs(cx-x)); foot_y=y
                    for r in range(foot_y-1,foot_y+2):
                        for c in range(foot_x-1,foot_x+2):
                            put(r,c,line)
                    put(foot_y,foot_x,seed)
                    dx=1 if x>foot_x else -1
                    cx=x+dx
                    while 0<=cx<W and g[cx,foot_y]==bg:
                        out[cx,foot_y]=seed; cx+=dx
    return out.tolist()

