# Rule candidate (line=hline case): bg fills; hline row L with color cL. For each seed s:
#  - cells strictly between seed and line along seed column: seed color (unless inside band)
#  - band rows L-1 and L+1, cols sx-1..sx+1: line color (clipped)
#  - cell (L,sx): seed color
def solve(I):
    I=np.array(I); H,W=I.shape
    cnt=Counter(I.flat); bg=cnt.most_common(1)[0][0]
    # find full line rows/cols and their color; seeds = other non-bg color(s)
    line=None
    for y in range(H):
        if len(set(I[y]))==1 and next(iter(set(I[y])))!=bg: line=('h',y,int(I[y,0])); break
    if line is None:
        for x in range(W):
            if len(set(I[:,x]))==1 and next(iter(set(I[:,x])))!=bg: line=('v',x,int(I[0,x])); break
    ('h' if line[0]=='h' else 'v'), lp, lc=line
    O=I.copy()
    seeds=[(y,x) for y in range(H) for x in range(W) if I[y,x]!=bg and I[y,x]!=lc]
    sc=set(int(I[y,x]) for y,x in seeds)
    seeds=list(seeds)
    if line[0]=='h':
        L=lp
        for sy,sx in seeds:
            col=int(I[sy,sx])
            for y in range(min(sy,L)+1,max(sy,L)):  # cells strictly between seed and line
                if not(L-1<=y<=L+1 and abs(y-L)<=1 and abs(x-sx)<=1 if False else True):
                    if y!=L-1 or not (sx-1<=x<=sx+1): pass
            # simpler: paint ray
            lo,hi=sorted((sy,L))
            for y in range(lo+1,hi):
                if L-1<=y<=L+1 and sx-1<=x:=sx<=sx+1 and False: pass
            x=sx
            for y in range(min(sy,L)+1,max(sy,L)):
                if not (L-1<=y<=L+1 and abs(y-(L if False else 0))==0) :
                    O[y,x]=col
            # band rows L-1,L+1 cols sx-1..sx+1 -> line color
            for y in (L-1,L+1):
                if 0<=y<H:
                    for dx in (-1,0,1):
                        ny,nx=y,sx+dx
                        if 0<=ny<H: O[ny,nx]=lc
            O[L,sx]=col
    else:
        C=lp
        for sy,sx in seeds:
            col=int(I[sy,sx]); y=sy
            for x in range(min(sx,C)+1,max(sx,C)):
                O[y,x]=col
            for x in (C-1,C+1):
                if 0<=x<W: O[sy,x]=lc
            O[sy,C]=col
