    cnt=Counter(I.flat); bg=cnt.most_common(1)[0][0]
    hlines=[(y,int(I[y,0])) for y in range(H) if len(set(I[y]))==1 and I[y,0]!=bg]
    vlines=[(x,int(I[0,x])) for x in range(W) if len(set(I[:,x]))==1 and I[0,x]!=bg]
    O=I.copy()
    def paint(cells,val):
        for y,x in cells:
            if 0<=y<H and 0<=x<W and O[y,x]==bg: O[y,x]=val
    if hlines and not vlines:
        lines=hlines
        horiz=True
    elif vlines and not hlines:
        lines=vlines; horiz=False
    else:
        # mixed: prefer single-line config; pick the one whose count matches typical; fallback: process both orientations? try nearest-line rule across both
        lines=hlines+vlines; horiz=None
    seeds=[(y,x) for y in range(H) for x in range(W) if I[y,x]!=bg and I[y,x] not in {c for _,c in lines}]
    if horiz is True:
        for sy,sx in seeds:
            c=int(I[sy,sx]); best=min(lines,key=lambda t:abs(t[0]-sy))
            L,lc=best
            for y in range(min(sy,L)+1,max(sy,L)):
                if y!=L-1 and y!=L+1: paint([(y,sx)],c)
            for r in (L-1,L+1):
                if 0<=r<H: paint([(r,sx+d) for d in (-1,0,1)],lc)
            paint([(L,sx)],c)
    elif horiz is False:
        for sy,sx in seeds:
            c=int(I[sy,sx]); best=min(lines,key=lambda t:abs(t[0]-sx))
            C,lc=best
            for x in range(min(sx,C)+1,max(sx,C)):
                if x!=C-1 and x!=C+1: paint([(sy,x)],c)
            for xc in (C-1,C+1):
                if 0<=xc<W: paint([(sy,xc)],lc)
            paint([(sy,C)],c)
    else:
        # both orientations present: ambiguous; choose nearest line overall? handle specially if needed
        pass
    return O.tolist()
